'use strict';
const {chromium}=require('playwright');const BASE=process.env.MSOS4_TEST_URL||'http://127.0.0.1:8765/';
const FINALS=`South Island SCM Championships 2026 - 28/08/2026 to 30/08/2026\nMeet Program - Friday Afternoon - warmup from 3:00pm\nEvent 1 Men 12 & Over 200 SC Meter IM\nHeat 1\n1 Aydan Brown M14 JASCB 2:32.49\n5 Matthew Callow M13 AQGCB 2:23.15\n6 Bodie Gilmour M14 WAVSL 2:27.14`;
(async()=>{const b=await chromium.launch({headless:true,args:['--no-sandbox']});const p=await b.newPage({viewport:{width:390,height:844},isMobile:true,hasTouch:true});try{await p.goto(BASE,{waitUntil:'domcontentloaded'});await p.waitForFunction(()=>MSOS4?.storageEngine?.hydrated?.()===true,{timeout:15000});await p.waitForFunction(()=>document.body.dataset.guardian==='pass',{timeout:15000});await p.evaluate(raw=>{const M=MSOS4;M.state.athletes=M.state.athletes||[];if(!M.state.athletes.some(a=>a.full_name==='Matthew Callow'))M.state.athletes.push({id:'mattc',full_name:'Matthew Callow',squad:'National',active:true});M.state.meetFieldDeck={meet_id:'sisc',source_id:'morning',title:'South Island SC Champs',races:[{event_number:1,event:'Men 12 & Over 200 SC Meter IM',distance:200,stroke:'IM',heat:4,lane:4,athlete_id:'mattc',athlete_name:'Matthew Callow',club:'AQGCB',seed_time:'2:19.53'}]};const parsed=M.meetSiscFormat.parse(raw,'finals');M.state.meetProgramBA={sources:[{source_id:'finals',raw,parsed}],commentaries:[],meetWorkspaces:{},nowKey:'',selectedKey:'',selectedAthleteId:'',expandedKey:'',selectedSourceId:'finals',selectedEventNumber:1};M.state.settings.view='meet';M.ui.renderMeet();M.meetProgramBA.render()},FINALS);await p.waitForTimeout(500);const row=p.locator('[data-ba-row].aqua',{hasText:'Matthew Callow'});if(await row.count()!==1)throw Error('finals Matthew AQ row missing');await row.tap();await p.waitForTimeout(400);const text=await row.innerText();if(!/Race history|Next 2|Seed/.test(text))throw Error('finals AquaGym row did not expand: '+text);console.log('SOUTH_ISLANDS_FINALS_EXPAND_PASS');}finally{await b.close()}})().catch(e=>{console.error(e.stack||e);process.exit(1)});
